    # Synchronize end of kernel with output data (multiple kernels
    # lead to same data node)
    if max_streams >= 0 and hasattr(node, "_cuda_stream"):
        backend = common.get_gpu_backend()

        for edge in dfg.out_edges(scope_exit):

