            if m is not None:
                nexpr = nexpr.subs(floor, int_floor(int_floor(m[c], m[d]), m[b]))
                processed += 1
                continue
            # Floor of floor: "floor(a / floor(c/d))"
            m = floor.match(sympy.floor(a / int_floor(c, d)))
            if m is not None:
                nexpr = nexpr.subs(floor, int_floor(m[a], int_floor(m[c], m[d])))
                processed += 1
                continue
