        """
        Evaluates integer ceiling division (``ceil(x / y)``).

        :param x: Numerator.
        :param y: Denominator.
        :return: Return value (literal or symbolic).
        """
        if x.is_Number and y.is_Number:
            return sympy.ceiling(x / y)

    def _eval_is_integer(self):
        return True


