            dstnode = edge.dst
            while isinstance(sdfg.arrays[dstnode.data], data.View):
                dstnode = dfg.out_edges(dstnode)[0].dst

            # We need the streams leading out of the output data
            for e in dfg.out_edges(dstnode):
