class left_shift(sympy.Function):

    @classmethod
    def eval(cls, x, y):
        """
        Evaluates a left shift.

        :param x: Value to shift.
        :param y: Value to shift by.
        :return: Return value (literal or symbolic).
        """
        if x.is_Number and y.is_Number:
            return x << y
        return x * (2**y)


class right_shift(sympy.Function):

    @classmethod
    def eval(cls, x, y):
        """
        Evaluates a right shift.

        :param x: Value to shift.
        :param y: Value to shift by.
        :return: Return value (literal or symbolic).
        """
        if x.is_Number and y.is_Number:
            return x >> y
        return int_floor(x, (2**y))


class ROUND(sympy.Function):

    @classmethod
    def eval(cls, x):
        """
        Evaluates rounding to integer.

        :param x: Value to round.
        :return: Return value (literal or symbolic).
        """
        if x.is_Number:
            return round(x)

    def _eval_is_integer(self):
        return True


class Is(sympy.Function):
