        """
        Evaluates logical or.

        :param x: First operand.
        :param y: Second operand.
        :return: Return value (literal or symbolic).
        """
        if x.is_Boolean and y.is_Boolean:
            return x or y

    def _eval_is_boolean(self):
        return True


